#!/usr/bin/env python3
# luxarch:cmdtext hook v4 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Shared: the EXECUTABLE part of a shell command, with data spans masked out.

luxarch's own line-regex rules run through `core._masked_lines`, which blanks string and comment
spans so an example inside a docstring cannot trip a rule. A Bash hook needs the same doctrine: a
heredoc body and a quoted literal are DATA the command carries, not the command being run. Without
it the hooks matched raw text, so writing a test or a doc ABOUT a dangerous pattern read as
executing it — that blocked routine work, and then blocked their own repair.

One lexer (`_lex`) reads a command once, as the shell does, and gives two views of it with offsets
kept (blanked characters become spaces, newlines stay):
  * the MASK: quoted spans ('…', "…", $'…'), heredoc bodies and comments blanked — what is run
  * the PLAIN text: comments and heredoc bodies blanked, quotes kept — what a run word points at
plus the heredocs it found. A `#` starts a comment only at the start of a word and outside quotes,
and a `<<` starts a heredoc only outside quotes and comments, as in the shell.

Also here: `simple_commands`/`git_calls`, which read a command as the argv the shell will run (for
checks a line regex cannot make: `git -C dir commit -n`), `executable_texts`, which opens the text
the shell runs from inside a command (`bash -c`, `$(…)`, `eval`), and `load_event`/`guarded`,
which make a deny hook refuse a tool call whose event it cannot read.
"""

from __future__ import annotations

import functools
import json
import os
import re
import shlex
import sys
from collections.abc import Callable
from typing import NamedTuple

# ── The lexer ───────────────────────────────────────────────────────────────────────────────────


class Heredoc(NamedTuple):
    marker: int  # index of the `<<`
    body_start: int
    body_end: int  # where the terminator line starts (the body excludes it)
    quoted: bool  # `<<'EOF'`, `<<"EOF"`, `<<\EOF`: the body is not expanded


class Lexed(NamedTuple):
    mask: str
    plain: str
    heredocs: tuple[Heredoc, ...]
    bounds: (
        str  # the mask with newlines inside quotes blanked too: where commands can end
    )


_WORD_BREAK = set(" \t\n;|&()<>")


def _blank_into(chars: list[str], start: int, end: int) -> None:
    for k in range(start, end):
        if chars[k] != "\n":
            chars[k] = " "


def _quoted_end(text: str, i: int, close: str, escapes: bool) -> int:
    """The index just past the quote closing the one at `text[i]` (the end when unclosed)."""
    j = i + 1
    while j < len(text):
        if escapes and text[j] == "\\":
            j += 2
            continue
        if text[j] == close:
            return j + 1
        j += 1
    return len(text)


def _heredoc_tag(text: str, i: int) -> tuple[str, bool, bool, int]:
    """(tag, strips tabs, quoted, index after the tag) for a `<<` at `text[i]`; tag '' if none."""
    j = i + 2
    dash = text.startswith("-", j)
    j += dash
    while j < len(text) and text[j] in " \t":
        j += 1
    start = j
    while j < len(text) and text[j] not in _WORD_BREAK:
        j = _quoted_end(text, j, text[j], text[j] == '"') if text[j] in "'\"" else j + 1
    word = text[start:j]
    return (
        word.replace("'", "").replace('"', "").replace("\\", ""),
        dash,
        word != _unq(word),
        j,
    )


def _unq(word: str) -> str:
    return word.replace("'", "").replace('"', "").replace("\\", "")


@functools.lru_cache(maxsize=256)
def _lex(text: str) -> Lexed:
    """`text` read once, as the shell reads it: linear in its length, cached per text."""
    mask, plain = list(text), list(text)
    quoted_newlines: list[int] = []
    heredocs: list[Heredoc] = []
    pending: list[tuple[str, bool, bool, int]] = []
    n, i, word_start = len(text), 0, True
    while i < n:
        c = text[i]
        if c == "\n":
            i += 1
            for tag, dash, quoted, marker in pending:
                body_start, j = i, i
                while j < n:
                    end = text.find("\n", j)
                    end = n if end < 0 else end
                    line = text[j:end]
                    if (line.lstrip("\t") if dash else line) == tag:
                        break
                    j = end + 1
                body_end = min(j, n)
                _blank_into(mask, body_start, body_end)
                _blank_into(plain, body_start, body_end)
                heredocs.append(Heredoc(marker, body_start, body_end, quoted))
                end = text.find("\n", body_end)
                i = (
                    n if body_end >= n or end < 0 else end + 1
                )  # the next body starts below
            pending.clear()
            word_start = True
            continue
        # Arithmetic, `$((…))` or a `((…))` command: `1<<2` in it is a shift, not a heredoc. Only
        # when it really closes with `))`; `$((cmd) )` is a command substitution.
        arith = _arith_end(text, i + 1) if text.startswith("$((", i) else None
        if arith is None and word_start and text.startswith("((", i):
            arith = _arith_end(text, i)
        if arith is not None:
            i = arith
            word_start = False
            continue
        if c == "\\":
            i += 2
            word_start = False
            continue
        if c == "'" or (c == "$" and text.startswith("$'", i)) or c == '"':
            start = i
            if c == '"':
                i = _quoted_end(text, i, '"', True)
            else:
                i = _quoted_end(text, i + (c == "$"), "'", c == "$")
            _blank_into(mask, start, i)
            quoted_newlines.extend(k for k in range(start, i) if text[k] == "\n")
            word_start = False
            continue
        if c == "#" and word_start:
            end = text.find("\n", i)
            end = n if end < 0 else end
            _blank_into(mask, i, end)
            _blank_into(plain, i, end)
            i = end
            continue
        if text.startswith("<<<", i):
            i += 3
            word_start = True
            continue
        if text.startswith("<<", i):
            tag, dash, quoted, after = _heredoc_tag(text, i)
            if tag:
                pending.append((tag, dash, quoted, i))
                i = after
                word_start = False
                continue
        # Not `{` (`${#x}` is a length) and not `)` (`$(a)#b` is one word): neither starts a
        # comment. A `#` read as a comment that is not one hides what follows from every hook.
        word_start = c in _WORD_BREAK and c != ")"
        i += 1
    bounds = list(mask)
    for k in quoted_newlines:
        bounds[k] = " "
    return Lexed("".join(mask), "".join(plain), tuple(heredocs), "".join(bounds))


def _arith_end(text: str, i: int) -> int | None:
    """For `((` at `text[i]`: the index after its `))` when it is arithmetic, else None."""
    outer = _matching_paren(text, i)
    if outer < len(text) and _matching_paren(text, i + 1) == outer - 1:
        return outer + 1
    return None


_CONTINUATION = re.compile(
    r"(?<!\\)((?:\\\\)*)\\\n"
)  # an odd run of backslashes, then newline


def _join_continuations(text: str, keep_length: bool) -> str:
    """Each line continuation joined, as the shell joins it; `a\\\\⏎b` (an escaped backslash) is not
    one. With `keep_length` the two characters become spaces, so offsets survive."""
    return _CONTINUATION.sub(lambda m: m.group(1) + ("  " if keep_length else ""), text)


def heredoc_bodies(text: str) -> list[str]:
    return [text[h.body_start : h.body_end] for h in _lex(text).heredocs]


# ── Shell words ─────────────────────────────────────────────────────────────────────────────────
# POSIX quoting. `shlex.split` walks a command one character at a time in Python: 34s for a 2 MB
# command, which a hook must judge inside Claude Code's timeout. A word is a run of unquoted
# characters, quoted spans ('…', "…", $'…', $"…") and backslash escapes.
_WORD = re.compile(
    r"""(?:[^\s'"\\$]+|\$'(?:\\.|[^'\\])*'|\$"(?:\\.|[^"\\])*"|\$|'[^']*'|"(?:\\.|[^"\\])*"|\\.?)+""",
    re.S,
)
_WORD_PART = re.compile(
    r"""\$'((?:\\.|[^'\\])*)'|\$?"((?:\\.|[^"\\])*)"|'([^']*)'|\\(.?)|([^'"\\]+)""",
    re.S,
)
_DQ_ESCAPE = re.compile(r"""\\([$`"\\\n])""")
_ANSI_ESCAPE = re.compile(
    r"\\(x[0-9a-fA-F]{1,2}|u[0-9a-fA-F]{1,4}|U[0-9a-fA-F]{1,8}|[0-7]{1,3}|c.|.)"
)
_ANSI_SIMPLE = {"a": "\a", "b": "\b", "e": "\x1b", "E": "\x1b", "f": "\f", "n": "\n", "r": "\r",
                "t": "\t", "v": "\v"}  # fmt: skip


def _ansi(m: re.Match[str]) -> str:
    s = m.group(1)
    if s[0] in "xuU" and len(s) > 1:
        return chr(int(s[1:], 16))
    if s[0].isdigit():
        return chr(int(s, 8) & 0xFF)
    if s[0] == "c" and len(s) == 2:
        return chr(ord(s[1].upper()) ^ 0x40)
    return _ANSI_SIMPLE.get(s, s)


def _unquote(word: str) -> str:
    out: list[str] = []
    for ansi, double, single, escaped, bare in _WORD_PART.findall(word):
        if bare:
            out.append(bare)
        elif ansi:
            out.append(_ANSI_ESCAPE.sub(_ansi, ansi))
        elif double:
            out.append(_DQ_ESCAPE.sub(r"\1", double))
        elif escaped:
            out.append("" if escaped == "\n" else escaped)
        else:
            out.append(single)  # also '', "" and $'', which add nothing
    return "".join(out)


def shell_split(text: str) -> list[str]:
    """`text` split into shell words with quoting removed, as the shell does (`$'…'` decoded,
    `\\$` unescaped in double quotes); ValueError on an unclosed quote."""
    words = _WORD.findall(text)
    if sum(len(w) for w in words) + len(re.findall(r"\s", text)) < len(text):
        raise ValueError("No closing quotation")
    return [_unquote(w) for w in words]


def _blank_str(text: str) -> str:
    return "".join("\n" if c == "\n" else " " for c in text)


def command_text(cmd: str) -> str:
    """`cmd` with heredoc bodies, quoted literals and comments blanked -- what is actually RUN."""
    return _lex(cmd).mask if cmd else ""


# Where a command ends: `&&`, `||`, `;`, a newline, a pipe (`|`, `|&`; not the `>|` redirection) and
# a background `&` (not the `&>`/`>&`/`2>&1` redirections).
_EXEC_SEPARATOR = re.compile(r"&&|\|\||;|\n|(?<!>)\|&?|(?<![>&<0-9])&(?![>&])")


def _segments(cmd: str) -> list[tuple[str, str, str]]:
    """(masked, plain, separator before it) per command segment."""
    if not cmd:
        return []
    lexed = _lex(cmd)
    masked = _join_continuations(lexed.bounds, keep_length=True)
    out: list[tuple[str, str, str]] = []
    start, sep = 0, ""
    for m in _EXEC_SEPARATOR.finditer(masked):
        out.append((masked[start : m.start()], lexed.plain[start : m.start()], sep))
        start, sep = m.end(), m.group(0)
    out.append((masked[start:], lexed.plain[start:], sep))
    return out


def segments(cmd: str) -> list[tuple[str, str]]:
    """(masked, raw) pairs, one per command segment.

    Two different questions need two different texts. "Is this dangerous verb actually being run?"
    must be asked of MASKED text, or a quoted example reads as an execution. "What is it pointing
    at?" must be asked of RAW text (quotes kept, comments and heredoc bodies blanked), or a quoted
    path vanishes and an unambiguous scratch target looks like an unknown one.

    Masking preserves length, so a boundary found in the masked string indexes the raw string too.
    """
    return [(m, r) for m, r, _sep in _segments(cmd)]


# ── Redirections ────────────────────────────────────────────────────────────────────────────────
# Found in the mask (a quoted `>` is data), with the target read from the raw text and unquoted, so
# `> "app/x.py"` names app/x.py. The operator is matched whole: `>>` is never `>` then `>`.
_REDIRECT_OP = re.compile(
    r"(?<![^\s(){}])(\d+|&)?(>>|>\||>&|<>|<&|<<<|<<-|<<|>|<)(?![>&|]?>)"
)


class Redirect(NamedTuple):
    fd: str  # '' (stdout for `>`, stdin for `<`), a digit, or '&' (both streams)
    op: str
    target: str  # the file, '&1'/'&-' for a duplication, '' when unreadable


def _word_end(raw: str, i: int) -> int:
    """Where the shell word starting at `raw[i]` ends (quotes kept together)."""
    while i < len(raw) and not raw[i].isspace() and raw[i] not in ";&|()<>":
        if raw[i] in "'\"":
            i = _quoted_end(raw, i, raw[i], raw[i] == '"')
        elif raw[i] == "\\":
            i += 2
        else:
            i += 1
    return min(i, len(raw))


def redirects(masked: str, raw: str) -> list[tuple[Redirect, int, int]]:
    """Each redirection in a segment, with its span (operator through target) in the segment."""
    out: list[tuple[Redirect, int, int]] = []
    for m in _REDIRECT_OP.finditer(masked):
        fd, op = m.group(1) or "", m.group(2)
        j = m.end()
        if op in (">&", "<&") and raw[j : j + 1] in "0123456789-" and raw[j : j + 1]:
            end = j + 1
            while end < len(raw) and raw[end].isdigit():
                end += 1
            out.append((Redirect(fd, op, "&" + raw[j:end]), m.start(), end))
            continue
        while j < len(raw) and raw[j] in " \t":
            j += 1
        end = _word_end(raw, j)
        try:
            target = " ".join(shell_split(raw[j:end]))
        except ValueError:
            target = raw[j:end]
        out.append((Redirect(fd, op, target), m.start(), end))
    return out


# ── The INVERSE lens: what a command WRITES ─────────────────────────────────────────────────────
# `command_text` masks the data to ask "is this verb being run?". A content guard needs the opposite:
# the data IS the subject. Four PreToolUse hooks — no-suppression, no-test-weakening, no-golden-edit,
# no-agent-deferral — guard content an Edit writes; a heredoc through Bash writes identical bytes,
# and Claude Code's auto mode recommends shell over the edit tools, so the shell route is guarded
# too.
#
# What a shell command will put on disk is not decidable in general (a `python3 -` heredoc can
# COMPUTE its output). What IS decidable, and covers every case the fleet has produced, is the
# literal text the command carries: heredoc bodies, a `sed -i` replacement, a redirected `printf`,
# what a pipeline hands to `tee`. A python heredoc that writes a file contains the forbidden token as
# a literal, so scanning the carried text catches it. Not seen: a file copied into place (`cp`,
# `install`, `dd`) from one written elsewhere.
# Writes that are not repo edits. A throwaway script in the scratchpad or /tmp is not the subject,
# and /dev/null is not a file.
_NOT_A_REPO_PATH = re.compile(r"^/dev/null$|^/tmp/|/scratchpad/|^\$?\{?TMPDIR")
_OUTPUT_OPS = {">", ">>", ">|", ">&", "<>"}


def _segment_argv(masked: str, raw: str) -> list[str]:
    if not masked.strip():
        return []
    return _strip_wrappers(_words(raw, masked))[1]


def _redirect_writes(masked: str, raw: str) -> list[str]:
    return [
        r.target
        for r, _s, _e in redirects(masked, raw)
        if r.op in _OUTPUT_OPS and r.target and not r.target.startswith("&")
    ]


def _sed_inplace_files(argv: list[str]) -> list[str]:
    """The files a `sed` edits in place: `-i` anywhere among its options (GNU takes it after the
    script too), with any suffix (`-i.bak`, `-i~`, `-i_bak`, BSD `-i ''`) or `--in-place`."""
    inplace, script_given, files = False, False, []
    i = 1
    while i < len(argv):
        w = argv[i]
        i += 1
        if w.startswith("--"):
            inplace = inplace or w.startswith("--in-place")
            if w in ("--expression", "--file"):
                script_given, i = True, i + 1
            script_given = script_given or w.startswith(("--expression=", "--file="))
        elif w.startswith("-") and len(w) > 1:
            for k, ch in enumerate(w[1:], 1):
                if ch == "i":
                    inplace = True
                    if k == len(w) - 1 and i < len(argv) and argv[i] == "":
                        i += 1  # BSD `-i ''`: an empty suffix as its own word
                    break  # the rest of the word is the suffix
                if ch in "ef":
                    script_given = True
                    i += 0 if k < len(w) - 1 else 1  # attached script, or the next word
                    break
        elif not script_given:
            script_given = True
        else:
            files.append(w)
    return files if inplace else []


def _program_writes(masked: str, raw: str) -> list[str]:
    """Files a `tee`, `sed -i` or `perl -i` segment writes: programs whose target is an argument,
    not a redirect. A pipeline is split into segments at `|`, so `… | tee -a app/x.py` is its own
    segment and its file is `tee`'s argument."""
    argv = _segment_argv(masked, raw)
    if not argv:
        return []
    base = os.path.basename(argv[0])
    if base == "tee":
        return [w for w in argv[1:] if not w.startswith("-")]
    if base == "sed":
        return _sed_inplace_files(argv)
    if base != "perl" or not any(re.match(r"^-[A-Za-z]*i", w) for w in argv[1:]):
        return []
    files: list[str] = []
    script_given = False
    i = 1
    while i < len(argv):
        w = argv[i]
        if w in ("-e", "-E") or re.match(r"^-[A-Za-z]*[eE]$", w):
            script_given = True
            i += 2
            continue
        if not w.startswith("-"):
            if script_given:
                files.append(w)
            script_given = True
        i += 1
    return files


def _segment_writes(masked: str, raw: str) -> list[str]:
    out = _redirect_writes(masked, raw)
    out.extend(_program_writes(masked, raw))
    return [t for t in out if t and not _NOT_A_REPO_PATH.search(t)]


def _shell_payload(raw: str) -> str:
    """A writing segment with its SHELL quoting removed: the bytes it puts on disk, not its syntax.

    A shell quote is not a string literal in the written file: in
    `sed -i 's/import os/import os  # noqa/' x.py` the quotes are what CARRY the suppression, so the
    payload is the unquoted words, one per line: a flag written after a word (`… # noqa/' -i f`) is
    not that word's text.
    """
    try:
        return "\n".join(shell_split(raw))
    except ValueError:
        return raw


def _written_parts(cmd: str) -> list[str]:
    segs = _segments(cmd)
    if not any(_segment_writes(m, r) for m, r, _ in segs):
        return []
    parts = heredoc_bodies(cmd)
    for i, (masked, raw, _sep) in enumerate(segs):
        if not _segment_writes(masked, raw):
            continue
        argv = _segment_argv(masked, raw)
        if argv and os.path.basename(argv[0]) == "tee":
            j = i  # `a | b | tee f` writes what the whole pipeline before it printed
            while j > 0 and segs[j][2] == "|":
                j -= 1
                parts.append(_shell_payload(segs[j][1]))
        parts.append(_shell_payload(raw))
    return parts


def written_content(cmd: str) -> str:
    """The literal text a Bash command will place into a repo file — '' when it writes nothing.

    Returns the heredoc bodies plus each writing segment, because a `sed -i` replacement and a
    redirected `printf` carry their payload inline rather than in a heredoc, and a `tee` writes what
    the pipeline before it printed. Text the shell runs from inside the command counts too.
    """
    if not cmd:
        return ""
    return "\n".join(p for text in executable_texts(cmd) for p in _written_parts(text))


def write_targets(cmd: str) -> list[str]:
    """Repo paths this command writes, from redirects, `sed -i`, `tee` and `perl -i` — never inferred.

    A `python3 - <<'PY'` heredoc that opens a file by a computed name is deliberately NOT parsed.
    Guessing the target of a deny hook is how a guard blocks the work that repairs it, so the
    path-gated hooks gain precise coverage here and keep a stated blind spot, rather than a broad one.
    """
    return [
        t
        for text in executable_texts(cmd or "")
        for masked, raw, _ in _segments(text)
        for t in _segment_writes(masked, raw)
    ]


def edited(ev: dict[str, object]) -> tuple[str, str, str]:
    """`(path, old_text, new_text)` for an Edit/Write event OR a Bash command that writes a file.

    ONE adapter, so a content guard is written once and covers both surfaces. A shell write has no
    "before" text to diff against, so `old` comes back empty and a new-vs-old guard degrades to
    "does the written text contain this at all" — stricter, and right here, because a heredoc
    usually rewrites a whole file rather than amending a line.
    """
    ti = tool_input(ev)
    cmd = text_field(ti, "command")
    if cmd:
        targets = write_targets(cmd)
        return (targets[0] if targets else "", "", written_content(cmd))
    return (
        text_field(ti, "file_path"),
        text_field(ti, "old_string"),
        text_field(ti, "new_string") or text_field(ti, "content"),
    )


# ── Reading the event: a deny hook fails CLOSED ─────────────────────────────────────────────────
# Claude Code reads a hook's exit 2 as "deny" and any other non-zero exit as a non-blocking error:
# the tool call goes ahead. So a deny hook that crashes on a payload it did not expect (a list where
# a string was, a missing object) has allowed the call. These helpers turn every such payload into
# `MalformedEvent`, and `guarded` turns that into a denial naming the hook. A field that is absent
# reads as '' (an Edit event has no `command`); a field that is present with the wrong type is
# malformed.


class MalformedEvent(ValueError):
    """The hook event cannot be read as the object a hook expects."""


# Bound to a name: an inline `except (A, B)` formats differently per Python target (PEP 758).
# RecursionError: JSON nested deeper than the parser's stack. ValueError includes UnicodeDecodeError.
_UNREADABLE_JSON = (ValueError, RecursionError)


def load_event(text: str | None = None) -> dict[str, object]:
    """The hook event from stdin (or `text`), as a JSON object."""
    try:
        ev = json.loads(sys.stdin.read() if text is None else text)
    except _UNREADABLE_JSON as exc:
        raise MalformedEvent(
            f"the event is not JSON ({exc.__class__.__name__})"
        ) from exc
    if not isinstance(ev, dict):
        raise MalformedEvent(f"the event is a JSON {type(ev).__name__}, not an object")
    return ev


def tool_input(ev: dict[str, object]) -> dict[str, object]:
    ti = ev.get("tool_input")
    if ti is None:
        return {}
    if not isinstance(ti, dict):
        raise MalformedEvent(f"tool_input is a {type(ti).__name__}, not an object")
    return ti


def text_field(mapping: dict[str, object], key: str) -> str:
    value = mapping.get(key)
    if value is None:
        return ""
    if not isinstance(value, str):
        raise MalformedEvent(f"{key} is a {type(value).__name__}, not a string")
    return value


def guarded(main: Callable[[], int], hook: str) -> int:
    """Run a deny hook's `main`; a call it cannot read, or cannot finish judging, is denied."""
    try:
        return main()
    except MalformedEvent as exc:
        why = f"the hook could not read this tool call: {exc}"
    except Exception as exc:  # a crash would exit 1, which Claude Code lets through
        why = f"the hook failed while judging this tool call ({exc.__class__.__name__}: {exc})"
    print(
        f"DENIED by {hook}: {why}.\n"
        "A deny hook that cannot judge a call cannot clear it. If Claude Code's event "
        "format changed or the hook is wrong, escalate to the luxarch maintainer (/escalate).",
        file=sys.stderr,
    )
    return 2


# ── Simple commands: what the shell will actually run ───────────────────────────────────────────
# A line regex anchored on `git\s+commit` misses every form git accepts between the program and its
# subcommand (`git -C dir commit`, `git -c k=v commit`), a short flag (`-n` is `--no-verify` on
# commit), a combined one (`-nm msg`) and an abbreviated long one (`--no-veri`). So the git-aware
# checks read argv: each simple command is tokenised the way the shell will tokenise it, its
# leading assignments and wrappers (`sudo`, `env`, `timeout 60`, …) are set aside, and git's
# global options are walked to its subcommand.
#
# Boundaries are found in the mask, so a `;` or a newline inside a quoted message does not split a
# command. Redirections are not words of the command: `2>/dev/null git commit -n` runs git, so they
# are cut out first. A line continuation joins its two lines into one word, as the shell does.
# Assignments carry across commands (`export X=…; git commit` sets git's environment), and words
# are expanded as the shell would where the value is known from the command itself: a literal
# variable, `${X:-default}`, a `{a,b}` brace.

_ASSIGNMENT = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)=(.*)$", re.S)
_KEYWORDS = ("(", "{", "!", "then", "do", "else", "if", "elif", "while", "until")
_FUNCTION_NAME = re.compile(r"^[\w.:-]+\(\)\{?$")
_DECLARES = {"export", "declare", "typeset", "readonly", "local"}
_WRAPPER_VALUE_OPTS = {
    "sudo": {"-u", "-g", "-C", "-D", "-h", "-p", "-r", "-t", "-U"},
    "doas": {"-u", "-C"},
    "env": {"-u", "-C", "--unset", "--chdir"},
    "nice": {"-n", "--adjustment"},
    "timeout": {"-s", "-k", "--signal", "--kill-after"},
    "stdbuf": {"-i", "-o", "-e"},
    "exec": {"-a"},
    "xargs": {"-I", "-L", "-n", "-P", "-s", "-d", "-E", "-a", "--arg-file", "--delimiter",
              "--max-args", "--max-lines", "--max-procs", "--max-chars", "--replace"},
}  # fmt: skip
_WRAPPERS = {"command", "nohup", "time", "builtin", "caffeinate", *_WRAPPER_VALUE_OPTS}
_VAR = re.compile(
    r"\$\{([A-Za-z_][A-Za-z0-9_]*)(?:(:?[-=])([^}]*))?\}|\$([A-Za-z_][A-Za-z0-9_]*)"
)


class SimpleCommand(NamedTuple):
    # NAME=value in force for it: its own prefix, and assignments made earlier in the command
    env: tuple[tuple[str, str], ...]
    # the program and its arguments, quoting removed, known values expanded
    argv: tuple[str, ...]
    # the segment as written (comments and heredoc bodies blanked)
    raw: str


def _exec_mask(cmd: str) -> str:
    """`cmd` with heredoc bodies, quoted spans, comments and line continuations blanked."""
    return _join_continuations(_lex(cmd).bounds, keep_length=True)


def _cut_redirections(raw: str, masked: str) -> str:
    """`raw` with each redirection (operator and target) blanked; the mask says which `>` is real."""
    out = list(raw)
    for _r, start, end in redirects(masked, raw):
        out[start:end] = " " * (end - start)
    return "".join(out)


def expand(word: str, values: dict[str, str]) -> str:
    """`word` with each variable whose value `values` knows expanded, `${X:-default}` included."""

    def var(m: re.Match[str]) -> str:
        name = m.group(1) or m.group(4)
        if name in values and (values[name] or m.group(2) not in (":-", ":=")):
            return values[name]
        if m.group(2):
            return m.group(3) or ""
        return m.group(0)  # unknown: left as written

    return _VAR.sub(var, word)


def _brace(word: str) -> tuple[int, int] | None:
    """The first `{a,b}` group in `word` (not `${…}`, no nested braces), as (open, close)."""
    i = word.find("{")
    while i >= 0:
        close = word.find("}", i)
        if close < 0:
            return None
        inner_open = word.find("{", i + 1, close)
        if inner_open >= 0:
            i = inner_open
            continue
        if (i == 0 or word[i - 1] != "$") and "," in word[i + 1 : close]:
            return i, close
        i = word.find("{", close)
    return None


def _braces(word: str, limit: int = 64) -> list[str]:
    """`word` brace-expanded as the shell does (`--{hard,}`), at most `limit` words."""
    group = _brace(word)
    if group is None:
        return [word]
    open_, close = group
    out: list[str] = []
    for alt in word[open_ + 1 : close].split(","):
        out.extend(_braces(word[:open_] + alt + word[close + 1 :], limit))
        if len(out) >= limit:
            break
    return out[:limit]


def _words(raw: str, masked: str) -> list[str]:
    text = _join_continuations(_cut_redirections(raw, masked), keep_length=False)
    try:
        words = shell_split(text)
    except ValueError:
        words = _cut_redirections(raw, masked).split()
    changed = True
    while words and changed:
        changed = False
        if words[0] in _KEYWORDS:
            words, changed = words[1:], True
        elif words[0] == "function" and len(words) > 1:
            words, changed = (
                words[2:],
                True,
            )  # `function f { …`: the body is the command
        elif _FUNCTION_NAME.match(words[0]):
            words, changed = words[1:], True  # `f() {` / `f(){`
        elif words[0][:1] in ("(", "{") and len(words[0]) > 1:
            words[0], changed = words[0][1:], True
    if words[:1] == [
        "case"
    ]:  # `case x in x) git commit -n ;;`: the command follows the pattern
        pattern = next(
            (j for j, w in enumerate(words) if w.endswith(")")), len(words) - 1
        )
        words = words[pattern + 1 :]
    elif len(words) > 1 and words[0].endswith(")") and "(" not in words[0]:
        words = words[1:]  # a later `case` pattern: `y) git push -f ;;`
    while words and words[-1] in (")", "}"):
        words = words[:-1]
    if words and words[-1].endswith(")") and words[-1] != ")":
        words[-1] = words[-1][:-1]
    return words


def _strip_wrappers(words: list[str]) -> tuple[list[tuple[str, str]], list[str]]:
    env: list[tuple[str, str]] = []
    i = 0
    while i < len(words):
        w = words[i]
        m = _ASSIGNMENT.match(w)
        if m:
            env.append((m.group(1), m.group(2)))
            i += 1
            continue
        base = os.path.basename(w)
        if base in _DECLARES:
            i += 1
            while i < len(words) and words[i].startswith(("-", "+")):
                i += 1  # `declare -x`, `export -n`
            continue
        if base not in _WRAPPERS:
            break
        value_opts = _WRAPPER_VALUE_OPTS.get(base, set())
        i += 1
        while i < len(words) and (
            words[i].startswith("-") or (base == "env" and _ASSIGNMENT.match(words[i]))
        ):
            if (
                base == "env"
                and words[i] in ("-S", "--split-string")
                and i + 1 < len(words)
            ):
                try:  # `env -S 'git commit -n'`: the value is the command, split once more
                    words = [*words[:i], *shell_split(words[i + 1]), *words[i + 2 :]]
                except ValueError:
                    words = [*words[:i], *words[i + 1].split(), *words[i + 2 :]]
                break
            m = _ASSIGNMENT.match(words[i])
            if m:
                env.append((m.group(1), m.group(2)))
            i += 2 if words[i] in value_opts else 1
        if base == "timeout" and i < len(words):
            i += 1  # the duration
    return env, words[i:]


def _flat_simple_commands(
    cmd: str, env: tuple[tuple[str, str], ...] = ()
) -> list[SimpleCommand]:
    """The simple commands written at this level of `cmd`; nested bodies are not opened."""
    if not cmd:
        return []
    out: list[SimpleCommand] = []
    inherited: list[tuple[str, str]] = list(env)
    for seg_masked, seg_raw, _sep in _segments(cmd):
        if not seg_masked.strip():
            continue
        own, argv = _strip_wrappers(_words(seg_raw, seg_masked))
        values = dict(inherited)
        own = [(k, expand(v, values)) for k, v in own]
        if not argv:
            inherited.extend(
                own
            )  # `export X=1` or a bare `X=1`: in force for what follows
            continue
        expanded = [b for w in argv for b in _braces(expand(w, values))]
        out.append(SimpleCommand((*inherited, *own), tuple(expanded), seg_raw))
    return out


# ── Text the shell runs that is written inside another command ──────────────────────────────────
# Masking blanks quoted spans because a quoted span is usually data. Some of it is run all the same:
# a `$(…)`, `<(…)`/`>(…)` or backtick substitution (inside double quotes too, and in an unquoted
# heredoc), the argument of `sh -c`/`bash -lc`, `eval`, `su -c`, `find -exec`, a heredoc, a
# here-string or a pipeline fed to a shell. Each such body is a command text of its own, judged
# like the outer one, with the environment of the command that runs it. Nesting deeper than
# `_MAX_NESTING` is denied: a hook that stops looking at some depth would pass everything below it.
# Not seen: a script file a shell runs, a command computed at run time, and what a program does
# inside a container or over ssh.

_SHELLS = {"sh", "bash", "zsh", "dash", "ksh", "mksh", "ash", "fish"}
_SHELL_VALUE_OPTS = {"-o", "+o", "-O", "+O", "--rcfile", "--init-file"}
_MAX_NESTING = 6


class NestedTooDeep(MalformedEvent):
    """A command nests shells or substitutions deeper than a hook will read."""


def _keyword_at(s: str, j: int, word: str) -> bool:
    end = j + len(word)
    return s.startswith(word, j) and (end == len(s) or s[end] in " \t\n;)&|")


def _matching_paren(s: str, i: int) -> int:
    """The index of the `)` closing the `(` at `s[i]`; len(s) when unclosed. Quotes and comments
    are respected, and so is `case`: the `)` ending a pattern (`x) cmd ;;`) closes nothing."""
    depth, quote, j, word_start = 0, "", i, True
    cases: list[int] = []  # the depth each open `case` sits at
    while j < len(s):
        c = s[j]
        if quote:
            if c == quote:
                quote = ""
            elif c == "\\" and quote == '"':
                j += 1
            j += 1
            word_start = False
            continue
        if c in "'\"":
            quote = c
        elif c == "\\":
            j += 1
        elif c == "#" and word_start:
            k = s.find("\n", j)
            j = len(s) if k < 0 else k
            continue
        elif c == "(":
            depth += 1
        elif c == ")":
            if cases and depth == cases[-1]:
                pass  # a `case` pattern ends
            else:
                depth -= 1
                if depth == 0:
                    return j
        elif word_start and _keyword_at(s, j, "case"):
            cases.append(depth)
        elif word_start and cases and _keyword_at(s, j, "esac"):
            cases.pop()
        word_start = c in " \t\n;|&("
        j += 1
    return len(s)


def _substitutions(text: str, quotes_count: bool = True) -> list[str]:
    """Bodies of `$(…)`, `<(…)`, `>(…)` and backticks in `text`. Single quotes stop expansion;
    double quotes do not. With `quotes_count` False (an unquoted heredoc body) every quote is a
    literal character."""
    out: list[str] = []
    i, quote, n = 0, "", len(text)
    while i < n:
        c = text[i]
        if quote == "'":
            quote = "" if c == "'" else quote
            i += 1
        elif c == "\\":
            i += 2
        elif quotes_count and not quote and text.startswith("$'", i):
            i = _quoted_end(text, i + 1, "'", True)  # `$'it\'s $(x)'` is one literal
        elif quotes_count and c == "'" and not quote:
            quote = "'"
            i += 1
        elif quotes_count and c == '"':
            quote = "" if quote == '"' else '"'
            i += 1
        elif text.startswith("$((", i) and _arith_end(text, i + 1) is not None:
            i = _arith_end(text, i + 1) or i + 1  # arithmetic runs nothing
        elif text.startswith("$(", i) or (
            not quote and text.startswith(("<(", ">("), i)
        ):
            end = _matching_paren(text, i + 1)
            out.append(text[i + 2 : end])
            i = end + 1
        elif c == "`":
            end = text.find("`", i + 1)
            end = n if end < 0 else end
            out.append(text[i + 1 : end])
            i = end + 1
        else:
            i += 1
    return out


def _runs_arg(argv: tuple[str, ...]) -> tuple[bool, int]:
    """(does this shell run its argument as a command, index after its options)."""
    i, runs = 1, False
    while i < len(argv) and argv[i][:1] in "-+" and argv[i] not in ("-", "--"):
        if argv[i] in _SHELL_VALUE_OPTS:
            i += 2
            continue
        runs = runs or (argv[i][:2] != "--" and "c" in argv[i][1:])
        i += 1
    return runs, i + (1 if i < len(argv) and argv[i] == "--" else 0)


def _printed(sc: SimpleCommand) -> str | None:
    """What an `echo`/`printf` prints, when it is a literal."""
    base = os.path.basename(sc.argv[0])
    if base == "echo":
        return " ".join(w for w in sc.argv[1:] if not re.fullmatch(r"-[neE]+", w))
    if base == "printf" and len(sc.argv) > 1:
        return " ".join(sc.argv[1:])
    return None


def heredoc_feeds(text: str) -> list[tuple[str, tuple[str, ...]]]:
    """Each heredoc body in `text`, with the words of the command its marker line feeds it to."""
    out: list[tuple[str, tuple[str, ...]]] = []
    for h in _lex(text).heredocs:
        line_start = text.rfind("\n", 0, h.marker) + 1
        words = tuple(
            w
            for sc in _flat_simple_commands(text[line_start : h.marker])
            for w in sc.argv
        )
        out.append((text[h.body_start : h.body_end], words))
    return out


def find_targets(argv: tuple[str, ...]) -> list[str]:
    """The paths a `find` reaches: each start directory joined with each name it matches."""
    starts: list[str] = []
    for w in argv[1:]:
        if w[:1] in ("-", "(", "!"):
            break
        starts.append(w)
    starts = starts or ["."]
    names = [
        argv[i + 1]
        for i, w in enumerate(argv[:-1])
        if w in ("-name", "-iname", "-path", "-ipath", "-regex", "-iregex")
    ]
    return [os.path.join(s, n) for s in starts for n in names] or starts


def argv_bodies(sc: SimpleCommand) -> list[str]:
    """Command text a program runs from its own arguments: `sh -c`, `eval`, `su -c`, `find -exec`,
    or a shell's here-string."""
    argv = sc.argv
    base = os.path.basename(argv[0])
    if base in _SHELLS:
        runs, i = _runs_arg(argv)
        if runs:
            return [argv[i]] if i < len(argv) else []
        masked = command_text(sc.raw)
        return [r.target for r, _s, _e in redirects(masked, sc.raw) if r.op == "<<<"]
    if base == "eval":
        return [" ".join(argv[1:])] if len(argv) > 1 else []
    if base == "su":
        for j, w in enumerate(argv[1:], 1):
            if w in ("-c", "--command") and j + 1 < len(argv):
                return [argv[j + 1]]
            if w.startswith("--command="):
                return [w.split("=", 1)[1]]
        return []
    if base == "find":
        found = " ".join(map(shlex.quote, find_targets(argv)))
        out: list[str] = []
        j = 1
        while j < len(argv):
            if argv[j] in ("-exec", "-execdir", "-ok", "-okdir"):
                k = j + 1
                while k < len(argv) and argv[k] not in (";", "+", "\\;"):
                    k += 1
                # `{}` is each path found: judge it as the paths the find reaches
                body = " ".join(shlex.quote(w) for w in argv[j + 1 : k])
                out.append(body.replace("'{}'", found))
                j = k
            j += 1
        return out
    return []


def _bodies(
    text: str, env: tuple[tuple[str, str], ...]
) -> list[tuple[str, tuple[tuple[str, str], ...]]]:
    """Every command text run from inside `text`, one level down, with the environment it runs in."""
    out: list[tuple[str, tuple[tuple[str, str], ...]]] = []
    lexed = _lex(text)
    for h in lexed.heredocs:
        body = text[h.body_start : h.body_end]
        line_start = text.rfind("\n", 0, h.marker) + 1
        line_end = text.find("\n", h.marker)
        line = text[line_start : len(text) if line_end < 0 else line_end]
        # The body is a script when the command it feeds is a shell: `bash <<'EOF'`, or a
        # `cat <<'EOF' | sh` whose pipeline ends in one.
        fed = [
            sc
            for m, r, sep in _segments(line)
            for sc in _flat_simple_commands(r, env)
            if (sep == "|" or "<<" in m) and os.path.basename(sc.argv[0]) in _SHELLS
        ]
        if fed and not _runs_arg(fed[0].argv)[0]:
            out.append((body, fed[0].env))
        elif not h.quoted:
            out.extend((s, env) for s in _substitutions(body, quotes_count=False))
    out.extend((s, env) for s in _substitutions(lexed.plain))
    flat = _flat_simple_commands(text, env)
    for sc in flat:
        out.extend((b, sc.env) for b in argv_bodies(sc))
        if os.path.basename(sc.argv[0]) in _SHELLS and not _runs_arg(sc.argv)[0]:
            # `bash <(echo '…')`: what the process substitution prints is the script
            for inner in _substitutions(sc.raw):
                for producer in _flat_simple_commands(inner, env)[:1]:
                    printed = _printed(producer)
                    if printed is not None:
                        out.append((printed, sc.env))
    segs = [s for s in _segments(text) if s[0].strip()]
    for k in range(
        1, len(segs)
    ):  # `echo '…' | sh`: what the stage before prints is the script
        if segs[k][2] != "|":
            continue
        sink = _flat_simple_commands(segs[k][1], env)
        source = _flat_simple_commands(segs[k - 1][1], env)
        if not sink or not source or os.path.basename(sink[0].argv[0]) not in _SHELLS:
            continue
        if _runs_arg(sink[0].argv)[0]:
            continue
        printed = _printed(source[0])
        if printed is not None:
            out.append((printed, sink[0].env))
    return [(b, e) for b, e in out if b.strip()]


def _texts(cmd: str) -> list[tuple[str, tuple[tuple[str, str], ...]]]:
    out: list[tuple[str, tuple[tuple[str, str], ...]]] = []

    def visit(text: str, env: tuple[tuple[str, str], ...], depth: int) -> None:
        if depth > _MAX_NESTING:
            raise NestedTooDeep(
                f"the command nests shells or substitutions more than {_MAX_NESTING} deep"
            )
        out.append((text, env))
        for body, body_env in _bodies(text, env):
            visit(body, body_env, depth + 1)

    if cmd:
        visit(cmd, (), 0)
    return out


def executable_texts(cmd: str) -> list[str]:
    """`cmd` and every command text the shell runs from inside it, outermost first."""
    return [text for text, _env in _texts(cmd)]


def executable_segments(cmd: str) -> list[tuple[str, str]]:
    """`segments` of every executable text of `cmd`: the masked/raw pairs a text check reads."""
    return [seg for text in executable_texts(cmd) for seg in segments(text)]


def simple_commands(cmd: str) -> list[SimpleCommand]:
    """Every simple command the shell runs for `cmd`, nested bodies included, with the
    environment in force for it and its argv."""
    return [sc for text, env in _texts(cmd) for sc in _flat_simple_commands(text, env)]


# ── git ─────────────────────────────────────────────────────────────────────────────────────────
# Options that take the NEXT word as their value, per subcommand. Knowing them keeps a commit
# message that reads `--no-verify` from being read as the flag, and finds the flags in a combined
# short option (`-anm msg`: a, n, then m takes the value).
_GIT_GLOBAL_VALUE = {"-C", "-c", "--git-dir", "--work-tree", "--namespace", "--super-prefix",
                     "--config-env", "--attr-source", "--list-cmds"}  # fmt: skip
_GIT_SHORT_VALUE = {
    "commit": "mFCct",
    "push": "o",
    "merge": "mFsX",
    "rebase": "xsXC",
    "clean": "e",
}
_GIT_SHORT_ATTACHED = {"commit": "Su", "merge": "S", "rebase": "S", "am": "pCS"}
_GIT_LONG_VALUE = {
    "commit": {"--message", "--file", "--reuse-message", "--reedit-message", "--author",
               "--date", "--template", "--fixup", "--squash", "--trailer", "--cleanup",
               "--pathspec-from-file"},
    "push": {"--push-option", "--receive-pack", "--exec", "--repo"},
    "merge": {"--message", "--file", "--strategy", "--strategy-option", "--into-name",
              "--cleanup"},
    "rebase": {"--onto", "--exec", "--strategy", "--strategy-option"},
    "clean": {"--exclude"},
    "config": {"--file", "--blob", "--type", "--default", "--comment", "--value"},
}  # fmt: skip
# The subcommands that take `--no-verify`: reading it anywhere else (`git log --grep`, `git grep -e`)
# would deny the very audit that looks for it.
GIT_NO_VERIFY_SUBS = {"commit", "push", "merge", "rebase", "am", "pull"}


class GitCall(NamedTuple):
    sub: str  # the subcommand, '' when git ran none
    flags: tuple[str, ...]  # long options without their value, short ones as `-x`
    positionals: tuple[str, ...]  # non-option words; everything after `--` included
    config: tuple[
        tuple[str, str | None], ...
    ]  # (lowercased key, value) for this run only
    env: tuple[tuple[str, str], ...]
    raw: str  # the simple command as written
    cwd: str = (
        ""  # where git runs, from `-C` (relative to the shell's directory); '' = there
    )


def _config_from_env(env: tuple[tuple[str, str], ...]) -> list[tuple[str, str | None]]:
    """Config git reads from the environment: GIT_CONFIG_KEY_<n>/VALUE_<n> and GIT_CONFIG_PARAMETERS."""
    values = dict(env)
    out: list[tuple[str, str | None]] = []
    for name, value in env:
        if name.startswith("GIT_CONFIG_KEY_"):
            out.append((value.lower(), values.get("GIT_CONFIG_VALUE_" + name[15:])))
        elif name == "GIT_CONFIG_PARAMETERS":
            for k, v in re.findall(r"'([^']+)'(?:='([^']*)')?", value):
                if not v and "=" in k:  # the older `'key=value'` form
                    k, _, v = k.partition("=")
                out.append((k.lower(), v or None))
    return out


def _git_argv_calls(
    argv: tuple[str, ...],
    sc: SimpleCommand,
    config: list[tuple[str, str | None]],
    depth: int,
) -> list[GitCall]:
    i, cwd = 1, ""
    while i < len(argv) and argv[i].startswith("-"):
        w = argv[i]
        nxt = argv[i + 1] if i + 1 < len(argv) else ""
        if w == "-C" and nxt:
            cwd = os.path.join(cwd, nxt)  # each `-C` is relative to the one before
        elif w == "-c":
            key, _, value = nxt.partition("=")
            config.append((key.lower(), value))
        elif w == "--config-env" or w.startswith("--config-env="):
            key = (nxt if w == "--config-env" else w.split("=", 1)[1]).partition("=")[0]
            config.append(
                (key.lower(), None)
            )  # the value lives in an env var we cannot read
        i += 2 if w in _GIT_GLOBAL_VALUE else 1
    sub = argv[i] if i < len(argv) else ""
    rest = argv[i + 1 :]
    alias = next((v for k, v in config if k == "alias." + sub.lower() and v), None)
    if (
        alias and depth < 4
    ):  # `-c alias.ci='commit --no-verify' ci`: judge what the alias runs
        if alias.startswith("!"):
            return [
                g
                for inner in simple_commands(alias[1:])
                for g in _git_calls_of(inner, depth + 1, list(config))
            ]
        try:
            words = shell_split(alias)
        except ValueError:
            words = alias.split()
        return _git_argv_calls(("git", *words, *rest), sc, config, depth + 1)
    flags, positionals = _parse_options(
        list(rest),
        _GIT_SHORT_VALUE.get(sub, ""),
        _GIT_SHORT_ATTACHED.get(sub, ""),
        _GIT_LONG_VALUE.get(sub, set()),
    )
    return [
        GitCall(
            sub, tuple(flags), tuple(positionals), tuple(config), sc.env, sc.raw, cwd
        )
    ]


def _git_calls_of(
    sc: SimpleCommand,
    depth: int = 0,
    config: list[tuple[str, str | None]] | None = None,
) -> list[GitCall]:
    if not sc.argv or os.path.basename(sc.argv[0]) != "git":
        return []
    return _git_argv_calls(
        sc.argv, sc, [*(config or []), *_config_from_env(sc.env)], depth
    )


def git_call(sc: SimpleCommand) -> GitCall | None:
    """`sc` read as a git invocation, or None when its program is not git."""
    calls = _git_calls_of(sc)
    return calls[0] if calls else None


def _parse_options(
    words: list[str], short_value: str, short_attached: str, long_value: set[str]
) -> tuple[list[str], list[str]]:
    flags: list[str] = []
    positionals: list[str] = []
    i = 0
    while i < len(words):
        w = words[i]
        i += 1
        if w == "--":
            positionals.extend(words[i:])
            break
        if w.startswith("--"):
            name = w.split("=", 1)[0]
            flags.append(name)
            if "=" not in w and name in long_value:
                i += 1
        elif w.startswith("-") and len(w) > 1:
            for j, ch in enumerate(w[1:]):
                flags.append("-" + ch)
                if ch in short_value:
                    if j == len(w) - 2:
                        i += 1  # `-m msg`: the value is the next word
                    break
                if ch in short_attached:
                    break
        else:
            positionals.append(w)
    return flags, positionals


def git_calls(cmd: str) -> list[GitCall]:
    """Every git invocation in `cmd`, a one-run alias expanded to what it runs."""
    return [g for sc in simple_commands(cmd) for g in _git_calls_of(sc)]


def is_abbrev(flag: str, option: str, shortest: int) -> bool:
    """git accepts any unambiguous prefix of a long option: `--no-veri` is `--no-verify`."""
    return len(flag) >= shortest and option.startswith(flag)


# `core.hooksPath` set to the committed `hooks/` is the fleet's own install, not a redirect.
_FLEET_HOOKS_PATH = {"hooks", "./hooks", "hooks/", "./hooks/"}
_FALSE = {"false", "no", "off", "0"}


def is_hook_redirect(key: str, value: str | None) -> bool:
    """Does setting `key` to `value` take git's hooks away from the committed ones?"""
    if key == "core.hookspath":
        return value not in _FLEET_HOOKS_PATH
    return key == "include.path" or bool(re.fullmatch(r"includeif\..+\.path", key))


def force_push(g: GitCall) -> bool:
    """A push that can overwrite what the remote holds: `--force`/`-f`, `--mirror`, a `+refspec`,
    or the same set through one-run config (`remote.<name>.push=+…`, `remote.<name>.mirror`)."""
    if g.sub != "push":
        return False
    if "-f" in g.flags or "--force" in g.flags or "--mirror" in g.flags:
        return True
    if any(p.startswith("+") for p in g.positionals):
        return True
    for key, value in g.config:
        if re.fullmatch(r"remote\..+\.push", key) and (value or "").startswith("+"):
            return True
        if (
            re.fullmatch(r"remote\..+\.mirror", key)
            and (value or "true").lower() not in _FALSE
        ):
            return True
    return False


def forced_clean(g: GitCall) -> bool:
    """`git clean` that deletes: `-f`, any prefix of `--force`, or `clean.requireForce` off."""
    if g.sub != "clean":
        return False
    if "-f" in g.flags or any(is_abbrev(f, "--force", 3) for f in g.flags):
        return True
    return any(
        k == "clean.requireforce" and (v or "").lower() in _FALSE for k, v in g.config
    )
